    "content": "25/08/2026 - 23:11 美国财政部长斯科特·贝森特周一公布了新一轮所谓的“二级”制裁，此次制裁并非直接针对伊朗，而是针对其贸易伙伴，重点关注黄金、科技、数字资产、航空和航运。然而，他并未具体说明制裁何时生效，也未透露美国可能制裁哪些国家。 伊朗当局宣布罕见地降低多年来实施的汽油配额，此前，任何试图超出配额的人都将面临更高的价格。55岁的房地产经纪人迈赫迪·亚兹迪安（Mehdi Yazdian）接受法新社采访时说道： “制裁自然会影响人们的生活；人们正在遭受苦难”，无论他们是“经济富裕”还是“贫困潦倒”…"
