    "content": "新华社大马士革8月25日电（记者林建杰）叙利亚库尔德武装主导的“叙利亚民主力量”领导人马兹卢姆·阿卜迪25日在叙总统府举行的新闻发布会上宣布，解散“叙利亚民主力量”及叙库尔德武装所成立的自治政府，并将其全面整合进叙利亚国家机构。 阿卜迪说，叙利亚进入一个“以和平和建设新叙利亚”为主题的新阶段，在与叙过渡政府总统艾哈迈德·沙拉达成协议、完成将军事力量整合进叙利亚过渡政府军队的进程后，“叙利亚民主力量”的使命结束，其作为一支独立的军事力量解散。 阿卜迪说：“我们希望今天成为一个真正的转折点，从战场走向建设，从战争时代走…"
