    "pub_date": "2026-08-26 04:45:17",
    "author": "",
    "description": "25/08/2026 - 22:33 她是乡村音乐界的绝对传奇人物，10 岁时就开始创作歌曲。 她创作了约 3,000 首歌曲，其中包括《Jolene》（1973 年）和《I Will Always Love You》（1974 年）等经典歌曲（惠特尼·休斯顿于 1992 年成功翻唱了这首歌曲）。 在她 60 年的职业生涯中，这位“乡村女王”发行了数十张专辑，销售了超过 1 亿张唱片，并且她的歌曲比任何其他歌手都更频繁地登上乡村音乐排行…",
    "content": "25/08/2026 - 22:33 她是乡村音乐界的绝对传奇人物，10 岁时就开始创作歌曲。 她创作了约 3,000 首歌曲，其中包括《Jolene》（1973 年）和《I Will Always Love You》（1974 年）等经典歌曲（惠特尼·休斯顿于 1992 年成功翻唱了这首歌曲）。 在她 60 年的职业生涯中，这位“乡村女王”发行了数十张专辑，销售了超过 1 亿张唱片，并且她的歌曲比任何其他歌手都更频繁地登上乡村音乐排行榜榜首。 她甚至凭借《溪流中的岛屿》等歌曲在流行音乐类别中获得桂冠，并主演了好莱…"
