    "title": "台风“紫檀”在广东湛江徐闻二次登陆",
    "link": "http://www.news.cn/20260826/bf680de98d0b4e8f9b0030f57ac403a4/c.html",
    "pub_date": "2026-08-26 04:28:36",
    "author": "胡拿云",
    "description": "新华社广州8月26日电（记者胡拿云）据广东省气象台消息，今年第19号台风“紫檀”（热带风暴级）的中心已于26日3时25分前后在广东省湛江市徐闻县沿海再次登陆，登陆时中心附近最大风力有8级（18米/秒），中心最低气压998百帕。登陆后将向北偏东方向移动，强度逐渐减弱。 此前，台风“紫檀”已于25日18时40分前后在海南省昌江黎族自治县昌化镇沿海地区登陆，登陆时中心附近最大风力8级（20米/秒）。",
    "content": "新华社广州8月26日电（记者胡拿云）据广东省气象台消息，今年第19号台风“紫檀”（热带风暴级）的中心已于26日3时25分前后在广东省湛江市徐闻县沿海再次登陆，登陆时中心附近最大风力有8级（18米/秒），中心最低气压998百帕。登陆后将向北偏东方向移动，强度逐渐减弱。 此前，台风“紫檀”已于25日18时40分前后在海南省昌江黎族自治县昌化镇沿海地区登陆，登陆时中心附近最大风力8级（20米/秒）。"
