    "content": "当地时间8月25日，在韩国庆尚北道庆山市与家人失去联系数日的25岁中国女留学生被发现遇害，一名30多岁的男子因涉嫌杀人被警方逮捕。警方调查发现，最初向警方报案称女子失踪的人正是该嫌疑人，他当时还自称是女子的男友。警方怀疑，其主动报案可能是为了干扰调查。 遇害的中国女留学生 据韩国警方消息，25日19时29分许，30多岁的男子A某因涉嫌杀害25岁中国籍女子B某被警方逮捕。警方随后在庆山市河阳邑A某的住所内发现了B某的遗体。 据悉，B某是庆山市一所大学研究生院的留学生。她于8月14日入境韩国，原计划领取课程结业证书，但…"
