    "content": "近日，央视新闻曝光了一起隔空猥亵案件。50岁男子苏某某冒充“16岁姐姐”，诱导一名10岁女孩发送私密照片，随后威胁恐吓。警方在苏某某的手机中，还发现了另外10名高度疑似的受害者线索。最终，苏某某因猥亵儿童罪，被依法判处有期徒刑五年六个月。 2023年，公安部网安局微信公众号曾刊文指出：“隔空猥亵”是指行为人以满足性刺激为目的，以互联网为媒介，打着“个性交友”“招募童星”等幌子，诱骗、胁迫未成年人进行“裸聊”，或发送“裸照”“裸体视频”等的违法犯罪行为。 通过官方定义可以看出，隔空猥亵虽然没有肢体接触，但诱骗、胁迫未…"
