    "link": "http://www.news.cn/20260826/25850d00b6af4cc49648bf641d05efb6/c.html",
    "pub_date": "2026-08-26 02:36:18",
    "author": "王钟毅 蒋彪",
    "description": "8月25日，在古巴首都哈瓦那，一辆老爷车驶过美国驻古巴大使馆前的反帝广场。新华社记者 蒋彪 摄 新华社哈瓦那8月25日电（记者王钟毅 蒋彪）古巴外交部长罗德里格斯25日谴责美国政府再次延长从1962年开始对古巴实施的《对敌贸易法》期限。 罗德里格斯通过社交媒体表示：“古巴以最强烈的措辞谴责美国政府将经济、商业和金融封锁再延长一年，这一针对我国人民的种族灭绝政策已持续超过六十年。”他还表示，“古巴不是威胁，封锁才是”。 美国政府《联邦政府…",
    "content": "8月25日，在古巴首都哈瓦那，一辆老爷车驶过美国驻古巴大使馆前的反帝广场。新华社记者 蒋彪 摄 新华社哈瓦那8月25日电（记者王钟毅 蒋彪）古巴外交部长罗德里格斯25日谴责美国政府再次延长从1962年开始对古巴实施的《对敌贸易法》期限。 罗德里格斯通过社交媒体表示：“古巴以最强烈的措辞谴责美国政府将经济、商业和金融封锁再延长一年，这一针对我国人民的种族灭绝政策已持续超过六十年。”他还表示，“古巴不是威胁，封锁才是”。 美国政府《联邦政府纪事》当天早些时候公布了美国总统特朗普于8月20日签署的总统令，把对古巴实施的《…"
