    "description": "新华社柏林8月25日电 据多家德国媒体25日报道，政府部门在调查本月初发生的莱比锡机场无人机爆炸物事件时，发现了第三架无人机及军用级炸药。 据西德意志广播电台等媒体报道，此前未被披露的第三架无人机在莱比锡机场西部的一处田地里被发现。调查人员认为，袭击策划者在此次事件中动用了多架无人机。 本月4日深夜，莱比锡机场工作人员在一架乌克兰安-124运输机附近发现一架装有爆炸物的无人机。调查显示，由于引信疑似出现故障，袭击未成功。 而在该无人机被…",
    "content": "新华社柏林8月25日电 据多家德国媒体25日报道，政府部门在调查本月初发生的莱比锡机场无人机爆炸物事件时，发现了第三架无人机及军用级炸药。 据西德意志广播电台等媒体报道，此前未被披露的第三架无人机在莱比锡机场西部的一处田地里被发现。调查人员认为，袭击策划者在此次事件中动用了多架无人机。 本月4日深夜，莱比锡机场工作人员在一架乌克兰安-124运输机附近发现一架装有爆炸物的无人机。调查显示，由于引信疑似出现故障，袭击未成功。 而在该无人机被发现后不久，一架敦豪货机在莱比锡机场附近飞行时与一个不明飞行物发生碰撞，随后改降…"
