    "description": "",
    "content": "快科技8月26日消息，在L3级自动驾驶到来之前，如今的辅助驾驶并不能替代人类司机，如果听之任之，甚至说完全依靠，除了危险之外，还可能触及法律责任。 据媒体 报道 ， 此前在G93成渝环线高速公路超车道上，一辆黑色SUV突然直接停在高速快车道，高速交警到场处置时发现驾驶员竟然在主驾驶酣睡。 经查，驾驶员王某江饮酒之后自行启动车辆驶入高速，途中了开启车辆智驾功能。 车辆后台数据显示，行驶途中车机多次发出驾驶员接管、分心预警，但当事人已经熟睡，没有任何响应。 系统识别驾驶员无反馈，触发安全保护逻辑，直接将车辆刹停在快车道…"
