    "content": "这是8月25日在东耶路撒冷阿盖卜村拍摄的遭下令拆除的近东救济工程处一所职业培训中心。新华社发（贾马尔·阿瓦德摄） 新华社耶路撒冷8月25日电（记者陈君清 冯国芮）以色列总理内塔尼亚胡25日发表声明称，当天启动了针对联合国近东巴勒斯坦难民救济和工程处（近东救济工程处）一个下属机构的“撤离工作”。 声明称，以色列“绝不允许一个其雇员参与恐怖主义和（2023年）10月7日大屠杀的组织在以色列领土内运作”，为此将动用一切手段对其采取行动。 据《以色列时报》报道，下令拆除的机构是近东救济工程处运营的一所职业培训中心，位于东耶…"
