    "content": "如何把项目经验沉淀下来？ 1 遇到有趣的设计，会把实现方案，自己用流程图等 uml ，把完整的方案，自己梳理一遍吗？ 2 感觉有帮助的代码段比较杂，自己记录得比较散。有时候记完了，自己也找不到，还不如搜索引擎查的快。但是有些公司内的封装的框架，这些好的代码段，是公网上面搜索不到的。 3 知识管理的问题：自己把技术经验记录下来，那么如何管理它，在自己需要时，如何快速找到的。如果说用标签管理的话，如何打标签？像这样三个维度？大家有没有什么好的管理软件，好的实践推荐的？ （我曾经想过用知识卡+打标签的方式，但因为没有反馈…"
