    "content": "新华社北京8月25日电（记者伍岳）中印边界问题特别代表第25次会晤25日在北京举行。中方特别代表、中共中央政治局委员、中央外办主任王毅同印方特别代表、国家安全顾问多瓦尔就中印边界问题和双边关系等进行了全面深入、友好坦诚的沟通。 王毅表示，中印关系健康稳定发展符合两国人民根本利益，具有全球和战略意义。近年来，习近平主席和莫迪总理在喀山、天津两次会晤，达成一系列重要共识，为两国关系改善发展指明方向。中方愿同印方从战略高度和长远角度把握两国关系，做睦邻友好的朋友、相互成就的伙伴，实现“龙象共舞”。 王毅表示，双方应总结历…"
