    "title": "德芙就短视频文案争议致歉：视频系由第三方团队发布，未严格执行审核流程",
    "link": "https://m.thepaper.cn/detail/33847782",
    "pub_date": "2026-08-25 23:48:20",
    "author": "@德芙悦时刻、@中国新闻网",
    "description": "8月25日，有媒体报道称，德芙官方旗舰店近日发布的一则短视频内容引发争议，具体文案为：跟男朋友要了很久的德芙七彩礼盒也没给我买，今天趁男朋友不在跟暧昧对象分享了。有网友表示，该文案令人浑身难受。 25日深夜，德芙官方发布致歉声明称，经核查，该短视频由第三方店铺运营团队创作并发布，未严格执行品牌方的内容审核流程。 涉事文案在表达方式和价值导向上存在明显不当，与德芙一直努力传递的真诚、温暖和尊重的品牌理念不符。 声明还称，在事件发生后，店铺…",
    "content": "8月25日，有媒体报道称，德芙官方旗舰店近日发布的一则短视频内容引发争议，具体文案为：跟男朋友要了很久的德芙七彩礼盒也没给我买，今天趁男朋友不在跟暧昧对象分享了。有网友表示，该文案令人浑身难受。 25日深夜，德芙官方发布致歉声明称，经核查，该短视频由第三方店铺运营团队创作并发布，未严格执行品牌方的内容审核流程。 涉事文案在表达方式和价值导向上存在明显不当，与德芙一直努力传递的真诚、温暖和尊重的品牌理念不符。 声明还称，在事件发生后，店铺客服团队对消费者质疑作出了不恰当的回应。 对此，德芙深表歉意，并认真复盘相关问题…"
