    "description": "新华社北京8月25日电（记者吴鸿波）25日，“长安新韵·大地华彩”西安户县农民画晋京展在北京国家金融信息大厦新华社美术馆开幕。来自中国美协、中国美术馆、故宫博物院、西安中国画院等单位的艺术家、学者齐聚一堂，共同见证这一民间艺术盛事。 本次展览精心遴选120幅户县农民画作品，分为“根脉传承·时代镜像”“百年党史·薪火相传”“长安新象·丝路交响”“绿水青山·祖脉秦岭”“文艺赋美·美美与共”“文脉绵长·气象万千”六大篇章。作品以浓烈饱满的色彩…",
    "content": "新华社北京8月25日电（记者吴鸿波）25日，“长安新韵·大地华彩”西安户县农民画晋京展在北京国家金融信息大厦新华社美术馆开幕。来自中国美协、中国美术馆、故宫博物院、西安中国画院等单位的艺术家、学者齐聚一堂，共同见证这一民间艺术盛事。 本次展览精心遴选120幅户县农民画作品，分为“根脉传承·时代镜像”“百年党史·薪火相传”“长安新象·丝路交响”“绿水青山·祖脉秦岭”“文艺赋美·美美与共”“文脉绵长·气象万千”六大篇章。作品以浓烈饱满的色彩和鲜活浪漫的笔触，将秦岭北麓的泥土芬芳与古都西安的时代脉动呈现在首都观众面前。 …"
