    "title": "香港与秘鲁自由贸易协定将于9月1日生效",
    "link": "http://www.news.cn/20260825/264b3e18f62544bb98c4423e3e9a50af/c.html",
    "pub_date": "2026-08-25 22:29:18",
    "author": "李嘉",
    "description": "新华社香港8月25日电 据香港特区政府新闻处25日消息，经双方完成所需内部程序，香港与秘鲁自由贸易协定（《自贸协定》）将于9月1日生效。《自贸协定》为香港制造商、服务提供者和投资者进入秘鲁市场时，提供具法律保障的更优惠待遇和市场准入，以创造商机，加强双边贸易和投资往来。 特区政府商务及经济发展局局长丘应桦说，秘鲁是香港在拉丁美洲的重要贸易伙伴。《自贸协定》涵盖货物贸易、服务贸易、投资、电子商贸及其他相关范畴，整体承诺超越双方各自在世界贸…",
    "content": "新华社香港8月25日电 据香港特区政府新闻处25日消息，经双方完成所需内部程序，香港与秘鲁自由贸易协定（《自贸协定》）将于9月1日生效。《自贸协定》为香港制造商、服务提供者和投资者进入秘鲁市场时，提供具法律保障的更优惠待遇和市场准入，以创造商机，加强双边贸易和投资往来。 特区政府商务及经济发展局局长丘应桦说，秘鲁是香港在拉丁美洲的重要贸易伙伴。《自贸协定》涵盖货物贸易、服务贸易、投资、电子商贸及其他相关范畴，整体承诺超越双方各自在世界贸易组织下所作承诺，有助进一步促进双边贸易和投资。 他表示，这是香港与拉丁美洲经济…"
