    "content": "新华社北京8月25日电（记者古一平）记者25日从农业农村部获悉，农业农村部近日印发《全国农产品产地市场体系发展“十五五”规划》。规划提出，到2030年，契合产业、产需衔接、高效顺畅、内联外通的现代农产品产地市场体系基本建成，农产品供给保障和服务带动小农户能力稳步提升。 农产品产地市场体系立足农产品生产区域，提供交易集散、加工仓储、物流配送、价格信息、品牌营销等综合服务，有效衔接生产与消费，是我国农产品市场和流通网络的重要组成，是保障农产品稳定安全供给的基础支撑。 规划显示，到2030年，农产品产地批发市场布局更加合…"
