    "pub_date": "2026-08-25 22:08:28",
    "author": "",
    "description": "中新网广西崇左8月25日电(李帅 郑清欣 黄艳梅)8月25日，受左江2026年第1号洪水影响，左江水域成片漂浮物下漂。当日16时，3艘在扶绥海螺码头附近防洪停泊船舶的螺旋桨被缠绕、舷侧受漂浮物和水流挤压，面临断缆走锚风险，船员向海事部门求救。当时左江扶绥水位达到86.22米，超警戒水位4.42米。",
    "content": "中新网广西崇左8月25日电(李帅 郑清欣 黄艳梅)8月25日，受左江2026年第1号洪水影响，左江水域成片漂浮物下漂。当日16时，3艘在扶绥海螺码头附近防洪停泊船舶的螺旋桨被缠绕、舷侧受漂浮物和水流挤压，面临断缆走锚风险，船员向海事部门求救。当时左江扶绥水位达到86.22米，超警戒水位4.42米。"
