    "content": "IT之家 8 月 25 日消息，Uber 优步今日在美国推出全新青少年安全保障措施，家长可在孩子乘坐网约车期间，通过手机查看车内实时视频监控。 IT之家了解到， 该功能可将司机手机的前置摄像头画面实时传输到家长手机上 。行程开始后，如果该功能处于可用状态，家长或监护人的手机将收到推送通知。如果他们选择观看监控，司机和乘客都会看到通知。 Uber 表示，只有青少年账户绑定的家长或监护人才能看到监控画面。行程结束后，司机、乘客和家长都无法再看到视频，官方宣称视频经过加密，但尚不清楚是否采用端到端加密。 此外，该功能如今…"
