    "author": "熊琳",
    "description": "2026年是“人类基因组计划第一份草图”公布25周年。8月24日至25日，昌平实验室举办人类基因组25周年国际研讨会。来自中国、美国、英国、瑞典等国家的30多位科学家汇聚北京，与百余位专家学者一起，共议“人类基因组计划”科学意义，交流最新研究成果，共话基因组学技术赋能生物医学新发展。 “人类基因组计划推动了分子生物学与细胞生物学、神经科学、药理学等几乎所有生物学和医学领域的进步。”昌平实验室主任谢晓亮在致辞中表示，作为唯一参与的发展中国…",
    "content": "2026年是“人类基因组计划第一份草图”公布25周年。8月24日至25日，昌平实验室举办人类基因组25周年国际研讨会。来自中国、美国、英国、瑞典等国家的30多位科学家汇聚北京，与百余位专家学者一起，共议“人类基因组计划”科学意义，交流最新研究成果，共话基因组学技术赋能生物医学新发展。 “人类基因组计划推动了分子生物学与细胞生物学、神经科学、药理学等几乎所有生物学和医学领域的进步。”昌平实验室主任谢晓亮在致辞中表示，作为唯一参与的发展中国家，中国为人类科学进步和生命健康事业做出了积极贡献。 与会现场，人类基因组计划中…"
