    "content": "第二届世界人形机器人运动会激战正酣。本届赛事迎来一次大升级，不仅赛项更多、队伍更庞大，机器人的能力也得到跨越式提升。 8月23日，“天工队”机器人（前）在400米（大型组）决赛中，它的成绩是38秒15。新华社记者 鞠焕宗 摄 运动比赛的背后，是对机器人产业核心技术的检验。让我们一起看看这场产业“随堂考”中，机器人的表现如何。 8月23日，天骄队机器人在跳远决赛中。最终，天骄队以7米97的成绩完赛，获得第一名。新华社记者 鞠焕宗 摄 记者：刘洋、鲍赫、孟菁 新华社音视频部制作"
